use super::*;

/// Take the COMMITTED store's file-side changes into the ledger, and nothing else.
///
/// Deliberately NOT [`sync_document`], which makes main EQUAL to the document. That is right for
/// `save()`, where the document is the whole graph, and wrong here: the ledger is shared by every
/// session on the machine, so a record another session advanced with `impl set` — legitimately ahead
/// of these files — would be reverted by making the two equal. MEASURED on this machine the day it was
/// written: 15 records were exactly that, against 2 genuine file-side edits.
///
/// So only two things move:
///
/// - a record whose body the ledger has NEVER held is a file-side edit, appended as a new revision;
/// - an id the files ONCE had (it carries an export watermark) and no longer do is tombstoned — a
///   decomposition retires its flat predecessor, and leaving it live has the export resurrect it
///   beside its own children.
///
/// An id with no watermark that the files lack is left alone: the files never had it, so it is a
/// record the LEDGER added and the files have simply not been exported yet.
pub fn adopt_files(conn: &Connection, doc: &Value, by: &str, note: Option<&str>) -> Result<Adopted, String> {
    let mut out = Adopted::default();
    let mut seen: std::collections::BTreeSet<String> = Default::default();
    for (key, tier) in [("implementations", TIER_IMPL), ("edges", TIER_EDGE)] {
        for rec in doc.get(key).and_then(Value::as_array).map(Vec::as_slice).unwrap_or(&[]) {
            let Some(id) = rec.get("id").and_then(Value::as_str) else { continue };
            seen.insert(id.to_string());
            let body = import::body_of(rec);
            if rev_holding(conn, id, &body)?.is_some() {
                out.untouched += 1;
                continue;
            }
            let rev = put_in(conn, MAIN, id, &body, Write::by(by).note(note).tier(tier))?;
            mark_exported(conn, id, rev)?;
            out.adopted += 1;
        }
    }
    let mut st = conn
        .prepare("SELECT r.id FROM records r JOIN exported e ON e.id = r.id")
        .map_err(|e| e.to_string())?;
    let once_exported: Vec<String> = st
        .query_map([], |r| r.get::<_, String>(0))
        .map_err(|e| e.to_string())?
        .collect::<Result<_, _>>()
        .map_err(|e| e.to_string())?;
    for id in once_exported {
        if !seen.contains(&id) {
            remove(conn, &id, by, note)?;
            conn.execute("DELETE FROM exported WHERE id = ?1", params![id])
                .map_err(|e| format!("cannot clear the watermark for '{id}': {e}"))?;
            out.tombstoned += 1;
        }
    }
    Ok(out)
}
